import json
import subprocess
import sys
import unittest
from pathlib import Path

from app import summarize


class SummaryTests(unittest.TestCase):
    def test_empty_json_list(self):
        result = subprocess.run(
            [sys.executable, str(Path(__file__).with_name("app.py"))],
            input="[]",
            text=True,
            capture_output=True,
            check=True,
        )
        self.assertEqual(json.loads(result.stdout), {"count": 0, "average": 0})

    def test_nonempty(self):
        self.assertEqual(summarize([2, 4, 6]), {"count": 3, "average": 4})


if __name__ == "__main__":
